    { "theme": "Produzindo textos para comunicar dados de pesquisa", "curriculumCode": "EF06M29", "description": "Aula de produção textual em que os alunos comunicam, por escrito, os resultados de pesquisas apresentados em gráficos e tabelas.", "materials": ["Gráficos e tabelas produzidos em aula anterior", "Folha pautada", "Modelo de texto informativo"], "steps": ["Retomar os gráficos e tabelas construídos pela turma em atividade anterior.", "Apresentar um modelo simples de texto que descreve dados de um gráfico.", "Pedir que cada aluno escreva um pequeno texto interpretando os dados do seu grupo.", "Revisar em duplas os textos produzidos, verificando clareza e precisão das informações.", "Selecionar alguns textos para leitura em voz alta para a turma.", "Fechar destacando a importância de comunicar dados de forma clara."] },
    { "theme": "Problemas com comprimento, massa, tempo, temperatura e área", "curriculumCode": "EF06M30", "description": "Aula de resolução e elaboração de problemas envolvendo cálculos de comprimento, massa, tempo, temperatura e área, usando unidades convencionais de medida.", "materials": ["Lista de problemas contextualizados", "Calculadora", "Instrumentos de medida (régua, balança, se disponíveis)"], "steps": ["Apresentar situações do cotidiano envolvendo diferentes grandezas.", "Resolver coletivamente um problema de cada tipo de grandeza no quadro.", "Distribuir uma lista variada de problemas para resolução em duplas.", "Propor que os próprios alunos elaborem um problema novo envolvendo uma das grandezas estudadas.", "Trocar os problemas elaborados entre duplas para resolução.", "Fechar com a correção coletiva dos problemas criados pelos alunos."] },
    { "theme": "Estimando medidas para decidir com bom senso", "curriculumCode": "EF06M31", "description": "Aula sobre estimativa de medidas de grandezas como estratégia para tomar decisões e verificar se um resultado é razoável.", "materials": ["Objetos variados da sala de aula", "Fita métrica ou trena", "Folha de registro"], "steps": ["Propor que os alunos estimem, sem medir, o comprimento de objetos da sala.", "Registrar as estimativas de cada aluno em uma tabela.", "Medir os objetos com fita métrica e comparar com as estimativas feitas.", "Discutir quais estimativas ficaram mais próximas do valor real e quais estratégias ajudaram.", "Repetir a atividade estimando outra grandeza, como massa de objetos.", "Fechar com uma reflexão sobre a utilidade de estimar em situações cotidianas."] },
    { "theme": "Escolhendo o instrumento certo para medir", "curriculumCode": "EF06M32", "description": "Aula prática sobre seleção e uso de instrumentos de medida — régua, esquadro, trena, relógio, cronômetro e balança — conforme a grandeza a ser medida.", "materials": ["Régua", "Trena", "Balança", "Cronômetro ou relógio", "Objetos variados para medição"], "steps": ["Apresentar os diferentes instrumentos de medida disponíveis e discutir para que serve cada um.", "Organizar estações de medição pela sala, cada uma com um instrumento diferente.", "Circular os grupos pelas estações, medindo objetos e registrando os resultados com a unidade adequada.", "Discutir qual instrumento seria mais adequado para medir grandezas maiores.", "Socializar os registros de cada estação com a turma.", "Fechar com uma tabela coletiva relacionando grandeza, instrumento e unidade de medida."] },
    { "theme": "Convertendo unidades de medida usuais", "curriculumCode": "EF06M33", "description": "Aula de resolução de problemas que exigem conversão entre unidades de medida de comprimento, massa, capacidade, tempo e área.", "materials": ["Tabela de conversão de unidades", "Lista de problemas", "Calculadora"], "steps": ["Apresentar as principais unidades de medida usadas no dia a dia e suas relações.", "Resolver coletivamente um problema simples de conversão de comprimento.", "Propor problemas envolvendo conversão de massa, capacidade e tempo para resolução em duplas.", "Circular pela sala auxiliando os alunos com dificuldades nas conversões.", "Corrigir coletivamente destacando os erros mais comuns.", "Fechar com uma tabela de conversões elaborada pela turma para consulta futura."] },
    { "theme": "Calculando o perímetro de figuras planas", "curriculumCode": "EF06M34", "description": "Aula de resolução e elaboração de problemas envolvendo o cálculo do perímetro de figuras planas.", "materials": ["Papel quadriculado", "Régua", "Figuras planas variadas impressas"], "steps": ["Retomar o conceito de perímetro como a soma das medidas dos lados de uma figura.", "Calcular coletivamente o perímetro de um retângulo desenhado no quadro.", "Propor que os alunos calculem o perímetro de diferentes figuras planas em papel quadriculado.", "Medir o perímetro de objetos reais da sala usando barbante e régua.", "Propor um problema de elaboração: criar uma figura com um perímetro específico dado.", "Fechar com a socialização das figuras criadas pelos alunos."] },
    { "theme": "Descobrindo a fórmula da área do retângulo", "curriculumCode": "EF06M35", "description": "Aula investigativa em que os alunos deduzem o procedimento para calcular a área de retângulos em malha quadriculada, chegando a uma fórmula.", "materials": ["Papel quadriculado", "Régua", "Retângulos de diferentes tamanhos desenhados na malha"], "steps": ["Apresentar um retângulo desenhado em malha quadriculada e pedir que os alunos contem os quadradinhos internos.", "Repetir a contagem com retângulos de diferentes tamanhos, registrando base, altura e área em uma tabela.", "Pedir que os alunos investiguem, em duplas, uma relação entre base, altura e área a partir da tabela.", "Socializar as hipóteses de fórmula levantadas pelos grupos.", "Testar a fórmula proposta (base × altura) com um novo retângulo.", "Fechar aplicando a fórmula para resolver problemas de área de retângulos."] },
    { "theme": "Jogos de estratégia em duplas", "curriculumCode": "EF06M36", "description": "Aula lúdica em que os alunos jogam em duplas jogos de estratégia, discutindo, selecionando e justificando as jogadas escolhidas.", "materials": ["Jogo de estratégia simples (damas, resta um, jogo da velha avançado)", "Tabuleiros ou folhas impressas"], "steps": ["Apresentar as regras do jogo de estratégia escolhido para a turma.", "Organizar os alunos em duplas para jogar, incentivando a discussão de cada jogada antes de executá-la.", "Circular pela sala observando as estratégias utilizadas pelas duplas.", "Parar o jogo em um momento e pedir que algumas duplas expliquem sua estratégia para a turma.", "Retomar o jogo incorporando as ideias compartilhadas.", "Fechar com uma roda de conversa sobre quais estratégias funcionaram melhor e por quê."] },
    { "theme": "Matemática nos jogos: pensando estrategicamente", "curriculumCode": "EF06M37", "description": "Aula que explora o conhecimento matemático presente em situações de jogos, incentivando o raciocínio lógico e estratégico dos alunos.", "materials": ["Jogos variados (cartas, tabuleiro, dados)", "Folha de registro de jogadas"], "steps": ["Escolher um jogo simples que envolva contagem, probabilidade ou lógica.", "Jogar uma rodada demonstrativa com toda a turma observando.", "Organizar os alunos em pequenos grupos para jogar e registrar as jogadas realizadas.", "Discutir quais conceitos matemáticos apareceram durante o jogo.", "Pedir que os grupos identifiquem uma 'melhor estratégia' e expliquem o raciocínio matemático por trás dela.", "Fechar com uma lista coletiva dos conceitos matemáticos identificados nos jogos."] },
    { "theme": "Matemática e cultura africana: um projeto de investigação", "curriculumCode": "EF06M38", "description": "Aula que inicia um projeto investigativo sobre a presença de conceitos e relações matemáticas na diversidade cultural africana.", "materials": ["Textos e imagens sobre matemática em culturas africanas (padrões geométricos, jogos como o Mancala)", "Cartolina", "Material de pesquisa"], "steps": ["Apresentar exemplos de padrões geométricos e jogos matemáticos de origem africana, como o Mancala/Oware.", "Formar grupos para pesquisar um aspecto da cultura africana com relação matemática.", "Orientar os grupos na coleta de informações e imagens para o projeto.", "Pedir que cada grupo identifique quais conceitos matemáticos aparecem no tema pesquisado.", "Organizar a produção de um cartaz ou apresentação sobre a pesquisa.", "Apresentar os projetos para a turma, destacando a diversidade cultural encontrada."] },
    { "theme": "Projeto sobre consumo e produção sustentáveis", "curriculumCode": "EF06M39", "description": "Aula que desenvolve um projeto envolvendo estilos de vida sustentáveis e práticas de produção e consumo responsáveis, usando a matemática como ferramenta de análise.", "materials": ["Dados sobre consumo (água, energia, resíduos)", "Calculadora", "Cartolina para o projeto"], "steps": ["Apresentar dados sobre consumo de água ou energia da escola ou da casa dos alunos.", "Discutir em grupo formas de reduzir o consumo e calcular a economia possível.", "Pedir que os grupos escolham um tema de consumo sustentável para investigar.", "Orientar a coleta e organização matemática dos dados.", "Elaborar propostas de ação sustentável baseadas nos cálculos realizados.", "Apresentar os projetos para a turma, com foco nos dados matemáticos que sustentam as propostas."] },
    { "theme": "Dobro de um número é o mesmo que seu quadrado?", "curriculumCode": "EF06M40", "description": "Aula investigativa que compara as relações de dobro e de quadrado de um número, verificando se essas operações são equivalentes.", "materials": ["Calculadora", "Tabela para registro", "Papel quadriculado (opcional)"], "steps": ["Perguntar aos alunos se eles acham que dobrar um número dá o mesmo resultado que elevá-lo ao quadrado.", "Pedir que testem a hipótese calculando o dobro e o quadrado de vários números.", "Organizar os resultados em uma tabela comparativa.", "Discutir em grupo em que caso (se algum) as duas operações coincidem.", "Verificar a hipótese com números maiores para confirmar a conclusão.", "Registrar coletivamente a justificativa da turma para a resposta encontrada."] },
    { "theme": "Quadrados perfeitos e raiz quadrada exata em sequências", "curriculumCode": "EF06M41", "description": "Aula investigativa sobre a existência de quadrados perfeitos em sequências figurais, relacionando o padrão observado à ideia de raiz quadrada exata.", "materials": ["Papel quadriculado", "Fichas ou blocos para montar sequências figurais", "Calculadora"], "steps": ["Apresentar uma sequência de figuras quadradas crescentes montadas com quadradinhos (1, 4, 9, 16).", "Pedir que os alunos contem os quadradinhos de cada figura e registrem a sequência numérica.", "Investigar em duplas se há um padrão entre a posição da figura na sequência e o número de quadradinhos.", "Relacionar os números encontrados à ideia de quadrados perfeitos e suas raízes quadradas exatas.", "Propor que prevejam quantos quadradinhos teria a próxima figura da sequência, sem desenhar.", "Fechar com o registro coletivo da relação entre quadrados perfeitos e raiz quadrada exata."] }
